// Format WhatsApp message for supplier
const items = $input.all();

const message = items.map(({ json }) => {
  const { product_name, suggested_quantity, supplier_phone, supplier_name } = json;
  return `Namaste ${supplier_name},\n\nPlease supply ${suggested_quantity} units of ${product_name}.\n\nThanks,\nSri Vinayaka Stores`;
})

return items.map((item, i) => ({
  json: {
    ...item.json,
    whatsapp_message: message[i],
    phone: item.json.supplier_phone
  }
}));

